from typing import List

class Solution:
    def subArrayRanges(self, nums: List[int]) -> int:
        total = 0
        for left in range(len(nums)):
            mn = mx = nums[left]
            for right in range(left, len(nums)):
                mn = min(mn, nums[right])
                mx = max(mx, nums[right])
                total += mx - mn
        return total

