from typing import List

class Solution:
    def subArrayRanges(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        for i, value in enumerate(nums):
            l = i
            while l > 0 and nums[l - 1] <= value:
                l -= 1
            r = i
            while r + 1 < n and nums[r + 1] < value:
                r += 1
            total += value * (i - l + 1) * (r - i + 1)
            l = i
            while l > 0 and nums[l - 1] >= value:
                l -= 1
            r = i
            while r + 1 < n and nums[r + 1] > value:
                r += 1
            total -= value * (i - l + 1) * (r - i + 1)
        return total

